def remove_control_characters(s):
    global _CONTROL_CHARACTERS_RE
    try:
        pattern = _CONTROL_CHARACTERS_RE
    except NameError:
        import re
        import sys
        ranges = []
        start = None
        for cp in range(sys.maxunicode + 1):
            if unicodedata.category(chr(cp))[0] == "C":
                if start is None:
                    start = cp
            elif start is not None:
                ranges.append((start, cp - 1))
                start = None
        if start is not None:
            ranges.append((start, sys.maxunicode))
        pattern = _CONTROL_CHARACTERS_RE = re.compile(
            "[" + "".join("\\U%08x-\\U%08x" % r for r in ranges) + "]"
        )
    return pattern.sub("", s)

def remove_control_characters(s):
    if type(s) is str and s.isprintable():
        return s
    return "".join(ch for ch in s if unicodedata.category(ch)[0]!="C")

