    counts = {}
    for win_len in range(1, term_length + 1):
        for i in range(len(doc) + 1 - win_len):
            window = doc[i : i + win_len]
            if not any(
                map(lambda word: word in common_words, window)
            ):
                term = " ".join(window)
                if  len(term) > 0 and not term.isspace():
